@Override
    public void renderToBuffer(PoseStack pPoseStack, VertexConsumer pBuffer, int pPackedLight, int pPackedOverlay, int pColor) {
        bb_main.render(pPoseStack, pBuffer, pPackedLight, pPackedOverlay, pColor);
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        ShieldEntity shield = new ShieldEntity(level, getShieldHP(spellLevel, entity));
        Vec3 spawn = RaycastBuilder.begin(level, entity)
                .range(3)
                .checkForBlocks(true)
                .build()
                .getLocation();
        shield.setPos(spawn);
        shield.setRotation(entity.getXRot(), entity.getYRot());
        level.addFreshEntity(shield);
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

@Override
    public boolean shouldApplyMixin(String targetClassName, String mixinClassName) {
        // Internal format of Compat$MODID$MixinName to automatically *not* apply mixins with that modid missing
        var nameT = mixinClassName.split("\\.");
        var name = nameT[nameT.length - 1];
        if (name.startsWith("Compat")) {
            String modid = name.substring(7, name.lastIndexOf('$'));
            return FMLLoader.getLoadingModList().getModFileById(modid) != null;
        }
        return true;
    }

